use vstd::prelude::*;

verus! {

// Specification function: checks if an integer is odd
spec fn is_odd(x: i32) -> bool {
    x % 2 != 0
}

// Specification function: checks if all elements in a[0..end) are even
spec fn all_even_before(a: Seq<i32>, end: int) -> bool {
    forall|i: int| 0 <= i < end ==> !is_odd(a[i])
}

fn find_first_odd(a: &[i32]) -> (result: (bool, usize))
    ensures
        // If found is false, all elements are even
        !result.0 ==> all_even_before(a@, a@.len() as int),
        // If found is true, index is in bounds
        result.0 ==> result.1 < a@.len(),
        // If found is true, element at index is odd
        result.0 ==> is_odd(a@[result.1 as int]),
        // If found is true, all elements before index are even
        result.0 ==> all_even_before(a@, result.1 as int),
{
    let mut i: usize = 0;
    
    while i < a.len()
        invariant
            i <= a.len(),
            // All elements before i are even
            all_even_before(a@, i as int),
        decreases a.len() - i,
    {
        if a[i] % 2 != 0 {
            assert(is_odd(a@[i as int]));
            return (true, i);
        }
        i = i + 1;
    }
    
    assert(i == a.len());
    assert(all_even_before(a@, a@.len() as int));
    (false, 0)
}

} // verus!

